// LongPi's seats in the DSH client: a full page with a 健康 entry in the
// sidebar, a greeting in place of the blank-session headline (which also
// places one row under the composer), an invisible prompt bridge in the input
// dock, a step in first-run onboarding, a LongPi page in settings, cards for
// five of its tools in the chat, quick actions under a turn that left
// something to do, a 健康 tab for DSH's right column, and a reminder pill in
// the shell overlay. Nothing visible sits above the composer.

import React from 'react'
import { PANEL_ID } from './constants.ts'
import { HomeHero } from './home.ts'
import { PromptBridge } from './home-actions.ts'
import { Icon } from './icons.ts'
import { setModelProbe, setModelSettings, type SettingsFace } from './model-status.ts'
import { Onboarding } from './onboarding.ts'
import { LongPiPage } from './page.ts'
import { HealthPane, PANE_ID, PANE_KIND, paneDefinition, setPaneOpener } from './pane.ts'
import { ReminderPill } from './pill.ts'
import { LongPiSettings } from './settings-page.ts'
import { injectStyles } from './styles/index.ts'
import { stopTimers } from './store.ts'
import { registerClientModules } from './modules.ts'
import { IntroCard, IntroDot } from './intro.ts'
import { openHealthChat, setWorkspaceOpener } from './health-chat.ts'
import { toolViewList } from './registry.ts'
import { TOOL_VIEWS } from './toolviews.ts'
import { longPiTurnDefinition, selectLongPiTail } from './turn-data.ts'
import { LongPiTurnTail } from './turn-tail.ts'
import { CodexOverlay, installPresentationShortcut, presentationCommand, PresentationButton } from './engage/slot.ts'
import { installActivity } from './engage/activity.ts'
import type { Face } from './types.ts'

const h = React.createElement

interface Slots {
  inject: (name: string, factory: () => unknown) => unknown
  register: (options: Record<string, unknown>, component: unknown) => unknown
}

/** The optional DSH services LongPi uses when they exist, as a callback of ctx.inject sees them. */
interface Optional {
  remote?: unknown
  settingsScope?: unknown
  /** The right column's tab-type registry (dsh-client-ui-sidebar-right). */
  sidebarRightTabs?: { register: (definition: unknown) => () => void }
  /** The right column's navigation face. */
  sidebarRight?: { openTab: (kind: string) => void }
  /** The conversation engine's Definition registry (dsh-client-ui-conversation). */
  uiConversation?: { events?: { register: (definition: unknown) => () => void } }
  /** DSH's workspace navigation (dsh-client-ui-workspace): opens a workspace's blank session. */
  uiWorkspace?: { openWorkspace: (workspaceId: string) => Promise<void> }
  effect?: (run: () => () => void, label?: string) => unknown
}

export interface ClientContext {
  slots: Slots
  layout?: { selectPanel: (id: string | null) => void }
  /** Cordis: run a callback once the named services exist (never, when they do not). */
  inject?: (deps: string[], callback: (ctx: Optional) => void) => unknown
}

export const inject = ['slots', 'layout']

/** The id of LongPi's page in DSH's settings (openSection('longpi')). */
export const SETTINGS_ID = 'longpi'

function PanelIcon(props: { size?: number }): React.ReactElement {
  // A dot until this install's welcome is seen (DSH's sidebar entry takes no badge of its own).
  return h(IntroDot, null, h(Icon, { name: 'health', size: props.size ?? 18 }))
}

export function apply(ctx: ClientContext): void {
  registerClientModules()
  injectStyles()
  // Looked up at click time: selectPanel throws for a panel that is not (yet) registered.
  const select = (id: string | null) => {
    try {
      ctx.layout?.selectPanel(id)
    } catch {
      // The panel is gone (plugin reloading); stay where we are.
    }
  }
  // A question from the page goes to 健康对话, never into whatever session was open last (C-04). When 健康对话
  // cannot be opened the caller says so and keeps the question out of other chats.
  const face = (): Face => ({
    openPage: () => select(PANEL_ID),
    openChat: () => openHealthChat(),
  })

  ctx.slots.inject('main', () => ctx.slots.register({ name: 'main', key: PANEL_ID, inject: face }, LongPiPage))
  ctx.slots.inject('sidebar.panellist', () => ctx.slots.register({ name: 'sidebar.panellist', id: PANEL_ID, order: 5, label: () => '健康' }, PanelIcon))
  // Rendered whenever a session exists, on the home and in a chat; draws nothing, inserts queued prompts.
  ctx.slots.inject('conversation.input.dock', () => ctx.slots.register({ name: 'conversation.input.dock', id: 'dsh-plugin-longpi', order: 90 }, PromptBridge))
  // No step in DSH's own first-run onboarding and no takeover of DSH's brand or blank-session home: LongPi adds
  // its 健康 page and settings section, and leaves the rest of DSH as it was.
  // After DSH's own pages (Models is order 10).
  ctx.slots.inject('settings.section', () => ctx.slots.register({ name: 'settings.section', id: SETTINGS_ID, order: 60, label: () => 'LongPi', inject: face }, LongPiSettings))
  for (const [key, view] of Object.entries(TOOL_VIEWS)) {
    ctx.slots.inject('tool.call.toolview', () => ctx.slots.register({ name: 'tool.call.toolview', key, inject: face }, view))
  }
  for (const view of toolViewList()) {
    ctx.slots.inject('tool.call.toolview', () => ctx.slots.register({ name: 'tool.call.toolview', key: view.tool, inject: face }, view.Component))
  }
  ctx.slots.inject('shell.overlay', () => ctx.slots.register({ name: 'shell.overlay', id: 'longpi-reminders', order: 50, inject: face }, ReminderPill))
  // The one prompt slot when the 健康 pane is not on screen (the stand-up line, or a reveal day's notice).
  ctx.slots.inject('shell.overlay', () => ctx.slots.register({ name: 'shell.overlay', id: 'longpi-codex-slot', order: 45, inject: face }, CodexOverlay))
  // 演示模式 beside DSH's settings at the sidebar foot (root-scoped, always on screen); also ⌘⌥P / Ctrl+Alt+P.
  ctx.slots.inject('sidebar.footer.action', () => ctx.slots.register({ name: 'sidebar.footer.action', id: 'longpi-presentation', order: 50 }, PresentationButton))
  // The one-time welcome after installing: non-blocking, dismissible, points at the 健康 entry.
  ctx.slots.inject('shell.overlay', () => ctx.slots.register({ name: 'shell.overlay', id: 'longpi-intro', order: 40, inject: face }, IntroCard))
  // Under a finished turn that left something to do: DSH folds the turn's cards, so their actions come back here.
  // Tried after the chain's shipped entries (produced files keep their row).
  ctx.slots.inject('conversation.chat.turnTail', () => ctx.slots.register({ name: 'conversation.chat.turnTail', select: selectLongPiTail, inject: face }, LongPiTurnTail))
  // The 健康 tab's body in DSH's right column; its type registers below when the column is there.
  ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({ name: 'sidebar.right.pane.tab', key: PANE_ID, inject: face }, HealthPane))
  // Whether a model key is set, for onboarding step 1: only when DSH exposes the Remote services
  // its Models page reads. Absent services leave the status unknown, and step 1 says nothing.
  if (typeof ctx.inject === 'function') {
    // A plugin reload or unload gives back the change stream, the poll and the listeners (F-5).
    ctx.inject(['slots'], (sub) => {
      sub.effect?.(() => () => stopTimers(), 'longpi: store timers')
      sub.effect?.(() => installActivity(), 'longpi: activity clock')
      sub.effect?.(() => installPresentationShortcut(), 'longpi: presentation shortcut')
    })
    ctx.inject(['commandUi'], (sub) => {
      const commands = (sub as { commandUi?: { register?: (command: ReturnType<typeof presentationCommand>) => () => void } }).commandUi
      if (commands?.register) sub.effect?.(() => commands.register!(presentationCommand()), 'longpi: /演示模式')
    })
    // Each turn's LongPi calls, published as the turn's data for the quick actions.
    ctx.inject(['uiConversation'], (sub) => {
      const events = sub.uiConversation?.events
      if (events) sub.effect?.(() => events.register(longPiTurnDefinition), 'longpi: turn data')
    })
    ctx.inject(['uiWorkspace'], (sub) => {
      const nav = sub.uiWorkspace
      if (!nav) return
      setWorkspaceOpener((id) => nav.openWorkspace(id))
      sub.effect?.(() => () => setWorkspaceOpener(null), 'longpi: 健康对话 opener')
    })
    ctx.inject(['sidebarRightTabs'], (sub) => {
      const tabs = sub.sidebarRightTabs
      if (tabs) sub.effect?.(() => tabs.register(paneDefinition(PanelIcon)), 'longpi: 健康 tab type')
    })
    ctx.inject(['sidebarRight'], (sub) => {
      const column = sub.sidebarRight
      if (!column) return
      setPaneOpener(() => {
        try {
          column.openTab(PANE_KIND)
        } catch {
          // No seat mounted (no session on screen): nothing to open into.
        }
      })
      sub.effect?.(() => () => setPaneOpener(null), 'longpi: 健康 tab opener')
    })
    ctx.inject(['remote', 'remote.llm', 'remote.credentials'], (sub) => {
      setModelProbe(sub.remote as Parameters<typeof setModelProbe>[0])
      sub.effect?.(() => () => setModelProbe(null), 'longpi: model status')
    })
    // The key reference the DeepSeek route reads (a custom apiKeyEnv); without it an unset default says nothing.
    ctx.inject(['settingsScope'], (sub) => {
      try {
        const scope = sub.settingsScope as { describe?: () => SettingsFace } | undefined
        setModelSettings(scope?.describe?.() ?? null)
      } catch {
        setModelSettings(null)
      }
      sub.effect?.(() => () => setModelSettings(null), 'longpi: model settings')
    })
  }
}
